
"use client";

import { useEffect, useRef, useState } from "react";
import {
  FaceLandmarker,
  FilesetResolver,
} from "@mediapipe/tasks-vision";

export default function FaceExpression() {
  const videoRef = useRef(null);

  const [expression, setExpression] = useState("Initializing...");
  const [error, setError] = useState("");
  const [isRunning, setIsRunning] = useState(false);

  useEffect(() => {
    let landmarker;
    let stream;
    let animationId;
    let cancelled = false;
    let lastVideoTime = -1;

    async function initialize() {
      try {
        const vision = await FilesetResolver.forVisionTasks(
          "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@latest/wasm"
        );

        if (cancelled) return;

        landmarker = await FaceLandmarker.createFromOptions(
          vision,
          {
            baseOptions: {
              modelAssetPath:
                "https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task",
            },
            runningMode: "VIDEO",
            numFaces: 1,
            outputFaceBlendshapes: true,
          }
        );

        if (cancelled) {
          landmarker.close();
          return;
        }

        stream = await navigator.mediaDevices.getUserMedia({
          video: true,
          audio: false,
        });

        const video = videoRef.current;

        if (!video || cancelled) {
          stream.getTracks().forEach((track) => track.stop());
          landmarker.close();
          return;
        }

        video.srcObject = stream;
        await video.play();

        if (cancelled) return;

        setIsRunning(true);

        function detect() {
          if (cancelled || !video || !landmarker) return;

          if (
            video.readyState >= 2 &&
            video.currentTime !== lastVideoTime
          ) {
            const result = landmarker.detectForVideo(
              video,
              performance.now()
            );

            const face = result.faceBlendshapes?.[0];

            if (!face) {
              setExpression("No face detected");
            } else {
              const scores = Object.fromEntries(
                face.categories.map((item) => [
                  item.categoryName,
                  item.score,
                ])
              );

              const smile =
                ((scores.mouthSmileLeft || 0) +
                  (scores.mouthSmileRight || 0)) / 2;

              const jawOpen = scores.jawOpen || 0;

              const blink = Math.max(
                scores.eyeBlinkLeft || 0,
                scores.eyeBlinkRight || 0
              );

              if (smile > 0.45) {
                setExpression("Smile detected 😊");
              } else if (jawOpen > 0.35) {
                setExpression("Mouth open 😮");
              } else if (blink > 0.65) {
                setExpression("Blink detected 👁️");
              } else {
                setExpression("Face detected — neutral movement");
              }
            }

            lastVideoTime = video.currentTime;
          }

          animationId = requestAnimationFrame(detect);
        }

        detect();
      } catch (err) {
        console.error("MediaPipe error:", err);

        if (!cancelled) {
          setError(
            "Camera/model error. Allow camera permission and check your internet connection."
          );
        }
      }
    }

    initialize();

    return () => {
      cancelled = true;
      cancelAnimationFrame(animationId);
      stream?.getTracks().forEach((track) => track.stop());
      landmarker?.close();
    };
  }, []);

  return (
    <main className="mx-auto max-w-xl space-y-5 p-6">
      <h1 className="text-2xl font-bold">
        AI Face Expression Detection
      </h1>

      <video
        ref={videoRef}
        autoPlay
        muted
        playsInline
        className="w-full rounded-xl bg-black"
      />

      <div className="rounded-xl border p-4">
        <p className="text-sm text-gray-500">
          Detected expression
        </p>

        <p className="mt-2 text-xl font-semibold">
          {expression}
        </p>

        {isRunning && (
          <p className="mt-2 text-sm text-green-600">
            Camera is running
          </p>
        )}

        {error && (
          <p className="mt-2 text-sm text-red-500">
            {error}
          </p>
        )}
      </div>
    </main>
  );
}
